"""Exact signed bytes generated by Connect's durable producer; synthetic DB only."""
import json
from pathlib import Path
import pytest
from test_tenant_support_inbox import A, CA, database, db
from test_integrated_connect_release import flow
from test_connect_channel_isolation import channels
import tenant_connect_transport as transport
import tenant_ai_agent_connect as ai


@pytest.mark.parametrize('reverse',[False,True])
def test_signed_producer_replay(channels,monkeypatch,reverse):
    fixture=json.loads((Path(__file__).parent/'fixtures/connect-call-signed.json').read_text())
    assert fixture['testOnly'] is True
    local=channels['db']
    secrets=transport._fernet().encrypt(json.dumps({'api_key':'synthetic','webhook_secret':fixture['secret']}).encode())
    local.execute("UPDATE saas_tenant_integrations SET secrets=%s WHERE tenant_id=%s::uuid AND provider='connect'",(secrets,A))
    local.execute("SELECT setval(pg_get_serial_sequence('saas_connect_conversations','lead_id'),1000,true)")
    local.commit()
    monkeypatch.setenv('AI_AGENTS_ENABLED','false');monkeypatch.setenv('AI_SIMULATION_ENABLED','false')
    def no_remote(*args,**kwargs):raise AssertionError('No external service calls')
    monkeypatch.setattr(transport,'_request',no_remote)
    for name in ('enqueue','mark_operator_reply','bind_unassigned_direct_agent'):
        monkeypatch.setattr(ai,name,no_remote)
    frames=fixture['frames'][::-1] if reverse else fixture['frames']
    bad=frames[0]
    with pytest.raises(transport.ConnectWebhookError,match='imzası'):
        transport.ingest(bad['rawBody'].encode(),'sha256=invalid',json.loads(bad['rawBody']))
    for frame in frames*2:
        raw=frame['rawBody'].encode();event=json.loads(raw)
        assert event['data']['channelId']==CA
        assert transport.ingest(raw,frame['signature'],event)
    rows=local.execute("SELECT message_type,raw FROM saas_crm_messages WHERE tenant_id=%s::uuid AND external_id LIKE 'connect:call:%%'",(A,))
    assert len(rows)==1 and rows[0]['message_type']=='call_invalidated'
    assert rows[0]['raw']['callRevision']==2
